mapper.update:
UPDATE pool_position p JOIN (
  SELECT option_id, user_id, SUM(amount) AS amt, COUNT(*) AS n FROM pool_bet
  WHERE id IN #{i} GROUP BY option_id, user_id
) d ON p.market_id = #{marketId} AND p.option_id = d.option_id AND p.user_id = d.user_id
SET p.amount = p.amount - d.amt, p.bet_count = p.bet_count - d.n, p.updated_at = #{now}

UPDATE pool_option_total t JOIN (
  SELECT option_id, SUM(amount) AS amt FROM pool_bet
  WHERE id IN #{i} GROUP BY option_id
) d ON t.option_id = d.option_id
SET t.amount = t.amount - d.amt, t.final_amount = CASE WHEN t.final_amount IS NULL THEN NULL ELSE t.final_amount - d.amt END, t.updated_at = #{now}
